package com.gestordevendas.api.inventory; import com.gestordevendas.api.common.security.CurrentUserService; import com.gestordevendas.api.tenant.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/inventory") public class InventoryController{private final InventoryLotService service;private final CurrentUserService current;private final TenantContextService tenants;private final TenantGuard guard;public InventoryController(InventoryLotService s, CurrentUserService c, TenantContextService t, TenantGuard g){service=s;current=c;tenants=t;guard=g;} @GetMapping("/lots") public List<InventoryProductResponse> lots(){var ctx=tenants.requireForUser(current.requireUserId());guard.requireOwnerOrAdmin(ctx);return service.summary(ctx.companyId());}}
